def calculate_max_reward(n: int, s: int, r: float) -> int:
    # Generate all possible triplets (a, b, c) such that a < b < c and a + b + c = s
    triplets = []
    for a in range(1, n - 2):
        for b in range(a + 1, n - 1):
            c = s - a - b
            if b < c <= n:
                triplets.append((a, b, c))

    # Use dynamic programming to find the maximum number of unique groups that can be formed
    dp = [0] * (n + 1)
    for triplet in triplets:
        a, b, c = triplet
        if c <= n:
            dp[c] += 1

    max_groups = 0
    for i in range(n, s - 2, -1):
        if dp[i] > 0:
            max_groups += 1

    # Calculate the total reward and round to the nearest integer
    total_reward = int(round(max_groups * r))

    return total_reward

