            if next_location not in visited and (current_location, next_location) in distances:
                visited.add(next_location)
                min_distance = min(min_distance, dfs(next_location, visited, path_length + distances[(current_location, next_location)]))
                visited.remove(next_location)

        return min_distance

    # Start from 'M'
    start_location = 'M'
    initial_visited = {'M'}

    # Calculate the shortest path
    shortest_path = float('inf')
    for next_location in distances[start_location]:
        if (start_location, next_location) in distances:
            visited = set(initial_visited)
            current_path_length = distances[(start_location, next_location)]
            shortest_path = min(shortest_path, dfs(next_location, visited, current_path_length))

    return shortest_path

