        "AAA",  # An wins in 3 sets
        "AAAB, AABA, BAAA",  # An wins in 4 sets
        "AABBAA, ABBAAB, BAABAA"  # An wins in 5 sets
    ]

    total_probability = 0.0

    for scenario in scenarios:
        if len(scenario) == 3:  # Scenario with 3 sets
            total_probability += probability_of_sequence(scenario)
        elif len(scenario) == 4:  # Scenario with 4 sets
            total_probability += binomial_coefficient(4, 2) * (probability_of_sequence(scenario))
