def solve_max_profit(initial_price=30, initial_orders=60, initial_qty=100, price_step=2, order_dec=4, qty_dec=2, cost_price=24, max_price=50):
    best_profit = 0
    optimal_price = 0

    for n in range((max_price - initial_price) // price_step + 1):
        selling_price = initial_price + n * price_step

        if selling_price > max_price:
            break

        num_orders = initial_orders - n * order_dec
        qty_per_order = initial_qty - n * qty_dec

        if num_orders <= 0 or qty_per_order <= 0:
            continue

        profit = (selling_price - cost_price) * (num_orders * qty_per_order)

        if profit > best_profit:
            best_profit = profit
            optimal_price = selling_price

    return round(optimal_price)

