    cross_product_AP_AB = cross_product(vec_AP, vec_AB)
    distance = dot_product(cross_product_AP_AB, (1, 0, 0)) / (dot_product(vec_AB, (1, 0, 0)))
    return abs(distance)

def solve_gps_problem(A: Tuple[float, float, float], B: Tuple[float, float, float], C: Tuple[float, float, float], D: Tuple[float, float, float]) -> float:
