    # Check if there's a critical point in (0, 1)
    for t in range(100):
        t_value = t / 100.0
        distance = sum_of_distances(t_value)
        distances_at_endpoints.append(distance)

    max_distance = max(distances_at_endpoints)
    # Find the corresponding M value
    for t, dist in zip(range(101), distances_at_endpoints):
        if abs(dist - max_distance) < 1e-6:
            return (3*t/100.0, 4 - 4*t/100.0, 5)

