def calculate_final_value():
    # Define colors and numbers
    colors = ['Blue', 'Red', 'Yellow']
    numbers = [1, 2, 3, 4]

    # Adjacency list for the octahedron (8 faces)
    adjacency_list = {
        0: [1, 2], 1: [0, 2, 3], 2: [0, 1, 3],
        3: [1, 2, 4], 4: [3, 5, 6], 5: [4, 6, 7],
        6: [4, 5, 7], 7: [5, 6]
    }

    # Function to check if a coloring is valid
    def is_valid_coloring(coloring):
        for i in range(8):
            for j in adjacency_list[i]:
                if coloring[i] == coloring[j]:
                    return False
        return True

    # Generate all possible colorings and number assignments
    count = 0
    for colors_perm in permutations(colors * 4, 8):
        for numbers_perm in product(numbers, repeat=8):
            valid_coloring = is_valid_coloring(colors_perm)
            if not valid_coloring:
                continue

            # Check the numbering constraint
            valid_numbering = True
            for i in range(8):
                for j in adjacency_list[i]:
                    if numbers_perm[i] == numbers_perm[j]:
                        valid_numbering = False
                        break
                if not valid_numbering:
                    break

            if valid_coloring and valid_numbering:
                count += 1

    # Calculate the result
    N = count // 8 + 16
    return float(N)

