def calculate_p(n_slots: int, n_books: int, scale_factor: int) -> float:
    def is_valid_distribution(slots):
        # Check if the distribution meets all conditions
        for i in range(len(slots)):
            if slots[i] == 2:
                if (i > 0 and slots[i-1] != 0) or (i < len(slots)-1 and slots[i+1] != 0):
                    return False
        return True

    total_ways = comb(n_slots + n_books - 1, n_books)

    valid_distributions = 0

    # Generate all possible distributions of books into slots
    for i in range(2 * (n_slots // 2) + 1):
        if i > n_books:
            break
        for j in range(n_slots - i):
            if i + j > n_books:
                continue
            k = n_books - i - j
            distribution = [0] * n_slots
            slots_with_2_books = min(i, 2)
            slots_with_1_book = min(j, 4) if (n_slots - i - j >= 4) else j
            empty_slots = max(0, k)

            # Place books according to the distribution
            for _ in range(slots_with_2_books):
                slot_index = next((idx for idx, val in enumerate(distribution) if val == 0 and (idx > 0 and distribution[idx-1] != 2)), None)
                if slot_index is not None:
                    distribution[slot_index] = 2
            for _ in range(slots_with_1_book):
                slot_index = next((idx for idx, val in enumerate(distribution) if val == 0), None)
                if slot_index is not None:
                    distribution[slot_index] = 1

            # Check if the distribution meets all conditions
            if is_valid_distribution(distribution):
                valid_distributions += 1

    probability = valid_distributions / total_ways
    return scale_factor * probability

